        get complete() {
            return this.closed;
        }

        push(text) {
            if (!text) return [];
            this.buffer += text;
            const elements = [];

            while (this.at < this.buffer.length) {
                const char = this.buffer[this.at];
                if (this.closed) {
                    this.at += 1;
                    continue;
                }

                if (!this.inElement) {
                    if (!this.opened) {
                        if (char === '[') {
                            this.opened = true;
                            this.at += 1;
                            continue;
                        }
                        if (isSpaceChar(char)) {
                            this.at += 1;
                            continue;
                        }
                        this.opened = true;
                        continue;
                    }
                    if (isSpaceChar(char) || char === ',') {
                        this.at += 1;
                        continue;
                    }
                    if (char === ']') {
                        this.closed = true;
                        this.at += 1;
                        continue;
                    }
                    this.inElement = true;
                    this.start = this.at;
                    this.depth = 0;
                }

                if (this.inString) {
                    if (this.escaped) {
                        this.escaped = false;
                    } else if (char === '\\') {
                        this.escaped = true;
                    } else if (char === '"') {
                        this.inString = false;
                    }
                } else if (char === '"') {
                    this.inString = true;
                } else if (char === '{' || char === '[') {
                    this.depth += 1;
                } else if (char === '}' || char === ']') {
                    this.depth -= 1;
                    if (this.depth === 0) {
                        elements.push(this.buffer.slice(this.start, this.at + 1));
                        this.inElement = false;
                        this.buffer = this.buffer.slice(this.at + 1);
                        this.at = 0;
                        continue;
                    }
                }
                this.at += 1;
            }
            return elements;
        }

        finish() {
            if (!this.inElement) return '';
            const rest = this.buffer.slice(this.start);
            this.inElement = false;
            this.buffer = '';
            this.at = 0;
            return rest;
        }
