      const parts = typeof m.content === 'string' ? [m.content] : Array.isArray(m.content) ? m.content.filter(p => p?.type === 'text').map(p => p.text || '') : [];
      for (const text of parts) for (const match of text.matchAll(CONTROL_RE)) found.push(match[1]);
