    if (!found.length) return null;
    if (found.length !== 1) throw Error('输出通道必须且只能开启一项。');
    return found[0];
  }
  function cleanMessages(messages, mode, guides) {
    const cleanText = text => String(text).replace(CONTROL_RE, '').replace(GUIDE_RE, (_, id, body) => {
      if (guides[id] !== undefined) throw Error('工具交稿协议条目重复：' + id);
