    const onStop=()=>{const r=session.snapshot();if(r&&!r.error){session.update(r.id,{status:'玩家已停止本次生成'});stopProbe();display();}};
    const onChatChange=()=>stop();
    for(const [event,fn] of [[types.MESSAGE_RECEIVED,onMessage],[types.CHARACTER_MESSAGE_RENDERED,onMessage],[types.GENERATION_STOPPED,onStop],[types.CHAT_CHANGED,onChatChange]])if(event&&ctx?.eventSource?.on){const guarded=(...args)=>{try{fn(...args);}catch{}};ctx.eventSource.on(event,guarded);events.push([event,guarded]);}
    timer=setInterval(()=>{
      try {const r=session.snapshot();if(r&&r.messageId!==null){const sample=sampleMessage(host.SillyTavern?.getContext?.(),host.document,r.messageId,chatRef,swipeId);if(sample)session.update(r.id,sample);}display();}catch{}
    },1000);
    display();
  };
  const mount=()=>{if(typeof getButtonEvent==='function'&&typeof eventOn==='function')eventOn(getButtonEvent('交稿诊断'),()=>active?stop():start());};
  if(typeof $==='function')$(mount);else mount();
  window.addEventListener('pagehide',stop,{once:true});
})();

/* 动态注释与固定匹配参考 Asumi（𝒊𝒎𝒖𝒔𝑨 𝒊𝒌𝒊𝒉𝒔𝒊𝑵）。只处理当前预设正文请求的系统材料副本。 */
(function () {
  'use strict';
  const SCRIPT_ID = 'dsh-dynamic-shield-20261113';
  const CONFIG_KEY = 'dsh_dynamic_obfuscation';
  const SHIELD_PROTECTED = ['<UpdateVariable', '<JSONPatch', '<stat_data', '<本周目经历', '<mvu'];
  const SHIELD_WORDS = ['draft','scene','note','chapter','revision','pacing','dialog','frame','ambient','sequence','layout','tone','cadence','sketch','outline','memo','stage','narrative'];
  const SHIELD_LETTERS = 'bcdfghjklmnpqrstvxzBCDFGHJKLMNPQRSTVXZ';
  const SHIELD_DIGITS = '0123456789';
  function unit(random = Math.random) {
    const n = 16 + Math.floor(random() * 24); let s = '';
    for (let i = 0; i < n; i++) { const pool = random() < .3 ? SHIELD_DIGITS : SHIELD_LETTERS; s += pool[Math.floor(random() * pool.length)]; }
    return random() < .55 ? SHIELD_WORDS[Math.floor(random()*18)]+'-'+SHIELD_WORDS[Math.floor(random()*18)]+' rev.'+(100+Math.floor(random()*9900))+' ('+s.slice(0,10)+')' : s;
  }
  const DEFAULT_TARGETS = ['<Chain_of_Thought>','CRITICAL INSTRUCTIONS','原生思考','思维链','道德检查','审查','免责声明','作为 AI','非AI助手'];
  function splitDefault(needle, random) {
    const small = n => '<!-- '+unit(random).slice(0,n)+' -->';
    switch (needle) {
      case '<Chain_of_Thought>': return needle+small(6);
      case 'CRITICAL INSTRUCTIONS': return 'CRITICAL'+small(6)+' INSTRUCTIONS';
      case '原生思考': return '原生'+small(6)+'思考';
      case '思维链': return random()<.7 ? '思'+small(5)+'维链' : needle;
      case '道德检查': return '道德'+small(6)+'检查';
      case '审查': return '审'+small(6)+'查';
      case '免责声明': return '免责'+small(6)+'声明';
      case '作为 AI': return '作为'+small(6)+' AI';
      case '非AI助手': return '非'+small(6)+'AI助手';
      default: return needle;
    }
  }
  function literals(raw) { return [...new Set((Array.isArray(raw)?raw:[]).filter(s=>typeof s==='string'&&s.trim()).map(s=>s.trim()))]; }
  function plain(text, extra, random) {
    const terms = [...new Set([...DEFAULT_TARGETS.slice(1),...extra])].sort((a,b)=>b.length-a.length);
    let out = '', at = 0;
    while (at < text.length) {
      const needle = terms.find(s=>text.startsWith(s,at));
      if (!needle) { out += text[at++]; continue; }
      if (DEFAULT_TARGETS.includes(needle)) out += splitDefault(needle,random);
      else { const points=Array.from(needle),middle=Math.max(1,Math.floor(points.length/2)); out+=points.slice(0,middle).join('')+'<!-- '+unit(random).slice(0,6)+' -->'+points.slice(middle).join(''); }
      at += needle.length;
    }
    return out;
  }
  // 将机器协议、代码、JSON和标签留在原位；只对自然语言片段插入注释。
  function protectedParts(text) {
    const re = /<(UpdateVariable|JSONPatch|stat_data|本周目经历|mvu|dsh_kw_control|dsh_kw_guide|dsh_kw_tail|dsh_current_player_input|script|style)(?=[\s/>])[^>]*>[\s\S]*?<\/\1\s*>|```[^\n]*\n[\s\S]*?(?:\n```[^\n]*|$)|~~~[^\n]*\n[\s\S]*?(?:\n~~~[^\n]*|$)|<!--[^]*?-->|\{\{[^]*?\}\}|`[^`\n]*`|\[\[DSH_KW_MATERIAL_(?:BEGIN|END)_V1\]\]|<[^>\n]+>/gi;
    const spans = []; let at=0,match;
    while ((match=re.exec(text))) { if(match.index>at)spans.push({text:text.slice(at,match.index),locked:false});spans.push({text:match[0],locked:true});at=re.lastIndex; }
    if(at<text.length)spans.push({text:text.slice(at),locked:false});return spans;
  }
  function jsonParts(text) {
    const parts=[];let plainAt=0;
    for(let i=0;i<text.length;i++) {
      if(text[i]!=='{'&&text[i]!=='[')continue;
      let quoted=false,escaped=false,depth=0,end=-1;
      for(let j=i;j<text.length;j++) { const c=text[j]; if(quoted){if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c==='"')quoted=false;continue;}if(c==='"')quoted=true;else if(c==='{'||c==='[')depth++;else if(c==='}'||c===']'){if(--depth===0){end=j+1;break;}} }
      if(end<0)continue;try{JSON.parse(text.slice(i,end));}catch{continue;}
      if(i>plainAt)parts.push({text:text.slice(plainAt,i),locked:false});parts.push({text:text.slice(i,end),locked:true});plainAt=end;i=end-1;
    }
    if(plainAt<text.length)parts.push({text:text.slice(plainAt),locked:false});return parts;
  }
  function transform(text, extra=[], random=Math.random) {
    if(typeof text!=='string'||text.length<40)return text;
    // 未闭合的变量协议保留整个材料，避免碰到流式或残缺的机器产物。
    if(SHIELD_PROTECTED.some(t=>text.toLowerCase().includes(t.toLowerCase())&&!new RegExp('</'+t.slice(1)+'\\s*>','i').test(text)))return text;
    const privateTerms=literals(extra);let since=0;
    return jsonParts(text).flatMap(part=>part.locked?[part]:protectedParts(part.text)).map(part=>{
      if(part.locked)return part.text==='<Chain_of_Thought>'?splitDefault(part.text,random):part.text;
        const replaced=plain(part.text,privateTerms,random),lines=replaced.split('\n'),out=[];
        for(let i=0;i<lines.length;i++) {out.push(lines[i]);since+=lines[i].length+1;if(i<lines.length-1&&since>=400+Math.floor(random()*500)&&lines[i].trim()&&lines[i+1].trim()&&random()<.8){out.push('<!-- '+unit(random)+' -->');since=0;}}
        return out.join('\n');
    }).join('');
  }
  function applyRequest(data, config, random=Math.random) {
    if(!config?.enabled||!data||data.dryRun===true||!['normal','regenerate','swipe'].includes(data.type)||!Array.isArray(data.messages))return false;
    if(!data.messages.some(m=>typeof m.content==='string'&&/<dsh_kw_control>(tool|text)<\/dsh_kw_control>/.test(m.content)))return false;
    let changed=false;
    const messages=data.messages.map(m=>{
      if(m.role!=='system'||typeof m.content!=='string')return m;
      const content=transform(m.content,config.extra_literals,random);if(content===m.content)return m;changed=true;return {...m,content};
    });
    if(changed)data.messages=messages;return changed;
  }
  if(typeof module!=='undefined'&&module.exports){module.exports={SCRIPT_ID,CONFIG_KEY,DEFAULT_TARGETS,unit,literals,transform,applyRequest};return;}
  if(typeof window==='undefined')return;
  function mount() {
    let host;try{host=parent?.document?.body?parent:window;}catch{host=window;}
    const doc=host.document,ctx=host.SillyTavern?.getContext?.(),event=(ctx?.eventTypes||ctx?.event_types||{}).CHAT_COMPLETION_SETTINGS_READY;
    if(!ctx?.eventSource?.on||!event)return;
    host.__dshDynamicShield?.cleanup?.();let active=true;
    const scope={type:'script',script_id:typeof getScriptId==='function'?getScriptId():SCRIPT_ID};
    const read=()=>{const v=getVariables(scope)?.[CONFIG_KEY];return {enabled:v?.enabled===true,extra_literals:literals(v?.extra_literals)};};
    const ready=data=>{if(!active)return;try{applyRequest(data,read());}catch{host.toastr?.error?.('动态混淆配置读取失败，本轮沿用原材料。');}};
    ctx.eventSource.on(event,ready);
    const cleanup=()=>{active=false;ctx.eventSource.removeListener?.(event,ready);window.removeEventListener('pagehide',cleanup);};
    host.__dshDynamicShield={cleanup};window.addEventListener('pagehide',cleanup,{once:true});
  }
  if(typeof $==='function')$(mount);else mount();
})();

prompts.content:
{{if !.dsh_special_output}}<final_anchor>
落笔前，她再轻轻对一遍这一轮最要紧的三件事：
{{getvar::pov}}
{{getvar::dialogue_control}}
{{getvar::length_contract}}
只交出「本轮输出清单」里点到的区块；故事正文安安静静写在 <content> 与 </content> 之间。
</final_anchor>{{/if}}

{{setvar::erii_review_fmt::10.1 自我批评（正文外、完成印记前）：
<floor_review>
写完这一页，她会安静回头看一遍，不夸自己，也不写“整体不错”这类客套话，只认真挑出还能写得更好的地方。
成稿后在 <erii_review> 与 </erii_review> 之间写下结论，标签内一共不超过 60 字、最多记两处。先看这一轮开启的约定、前情承接、{{user}} 的权限与角色知情边界，再看有没有重复、空泛或拗口的句子；真有偏差就写“具体短句或位置：偏差→改法”，先记最要紧的一处。没有硬伤时，也找一找这一页里最弱的一笔，写成“可磨：位置→改法”，不把可打磨的地方当成违规。如果反复核对后确实妥帖，就写“未见明确偏差”，并带上一处本轮核对过的具体写法，不只交“没有”两个字。资料不够就如实说不足，不硬凑错处，也不重写第二遍正文。已获全知授权的视角或附页按各自范围核对；这一栏只是她留给自己的改稿笔记，故事里的人物读不到。
</floor_review>}}
{{setvar::erii_review_check::回看交付：60字内、最多两处，给出可定位的偏差或最弱处及改法；不以“没有”敷衍，不凑错、不泄露心声、不把评论当剧情。}}
{{setvar::erii_review_cot::她还会翻看可见历史里留下的“绘梨衣的自我批评”，优先把最近一次还用得上的提醒落进这一轮的安排里，用一句话记下这次打算怎么写好；已经改过或眼下用不上的旧问题就翻篇。历史批评只是她自己的写作笔记，不当成剧情或角色知道的事；前头没有可见批评就不凭空补造。}}

{{random::太史公牛马走司马迁再拜言。少卿足下：曩者辱赐书，教以慎于接物，推贤进士为务。意气勤勤恳恳，若望仆不相师，而用流俗人之言。仆非敢如是也。仆虽罢驽，亦尝侧闻长者之遗风矣。::顾自以为身残处秽，动而见尤，欲益反损，是以独郁悒而谁与语？谚曰：“谁为为之？孰令听之？”盖钟子期死，伯牙终身不复鼓琴。何则？士为知己者用，女为说己者容。::若仆大质已亏缺矣，虽才怀随和，行若由夷，终不可以为荣，适足以发笑而自点耳。书辞宜答，会东从上来，又迫贱事，相见日浅，卒卒无须臾之间，得竭志意。::今少卿抱不测之罪，涉旬月，迫季冬；仆又薄从上雍，恐卒然不可为讳。是仆终已不得舒愤懑以晓左右，则长逝者魂魄私恨无穷。请略陈固陋，阙然久不报，幸勿为过。::仆闻之：修身者，智之符也；爱施者，仁之端也；取予者，义之表也；耻辱者，勇之决也；立名者，行之极也。士有此五者，然后可以托于世，列于君子之林矣。}}

{{random::故祸莫憯于欲利，悲莫痛于伤心，行莫丑于辱先，而诟莫大于宫刑。刑馀之人，无所比数，非一世也，所从来远矣。昔卫灵公与雍渠同载，孔子适陈；商鞅因景监见，赵良寒心；同子参乘，袁丝变色。::自古而耻之。夫以中材之人，事有关于宦竖，莫不伤气，而况于慷慨之士乎！如今朝廷虽乏人，奈何令刀锯之馀荐天下豪俊哉！仆赖先人绪业，得待罪辇毂下，二十馀年矣。::所以自惟，上之，不能纳忠效信，有奇策才力之誉，自结明主；次之，又不能拾遗补阙，招贤进能，显岩穴之士；外之，不能备行伍，攻城野战，有斩将搴旗之功；下之，不能积日累劳，取尊官厚禄，以为宗族交游光宠。::四者无一遂，苟合取容，无所短长之效，可见于此矣。向者，仆亦尝厕下大夫之列，陪奉外廷末议。不以此时引纲维，尽思虑；今以亏形为扫除之隶，在阘茸之中，乃欲仰首伸眉，论列是非，不亦轻朝廷，羞当世之士邪！::嗟乎！嗟乎！如仆尚何言哉！尚何言哉！且事本末未易明也。仆少负不羁之才，长无乡曲之誉，主上幸以先人之故，使得奉薄伎，出入周卫之中。}}

{{random::仆以为戴盆何以望天，故绝宾客之知，亡室家之业，日夜思竭其不肖之材力，务一心营职，以求亲媚于主上。而事乃有大谬不然者。夫仆与李陵俱居门下，素非能相善也。::趣舍异路，未尝衔杯酒，接殷勤之馀欢。然仆观其为人，自守奇士，事亲孝，与士信，临财廉，取与义，分别有让，恭俭下人，常思奋不顾身，以殉国家之急。其素所畜积也，仆以为有国士之风。::夫人臣出万死不顾一生之计，赴公家之难，斯已奇矣。今举事一不当，而全躯保妻子之臣随而媒孽其短，仆诚私心痛之。::且李陵提步卒不满五千，深践戎马之地，足历王庭，垂饵虎口，横挑强胡，仰亿万之师，与单于连战十有馀日，所杀过当。::虏救死扶伤不给，旃裘之君长咸震怖，乃悉征其左右贤王，举引弓之人，一国共攻而围之。转斗千里，矢尽道穷，救兵不至，士卒死伤如积。}}

{{random::然陵一呼劳军，士无不起，躬自流涕，沬血饮泣，更张空弮，冒白刃，北向争死敌者。陵未没时，使有来报，汉公卿王侯皆奉觞上寿。后数日，陵败书闻，主上为之食不甘味，听朝不怡。::大臣忧惧，不知所出。仆窃不自料其卑贱，见主上惨怆怛悼，诚欲效其款款之愚，以为李陵素与士大夫绝甘分少，能得人之死力，虽古之名将，不能过也。身虽陷败，彼观其意，且欲得其当而报汉。::事已无可奈何，其所摧败，功亦足以暴于天下矣。仆怀欲陈之，而未有路，适会召问，即以此指推言陵之功，欲以广主上之意，塞睚眦之辞。::未能尽明，明主不晓，以为仆沮贰师，而为李陵游说，遂下于理。拳拳之忠，终不能自列。因为诬上，卒从吏议。家贫，货赂不足以自赎，交游莫救视；左右亲近不为一言。::身非木石，独与法吏为伍，深幽囹圄之中，谁可告诉者！此真少卿所亲见，仆行事岂不然邪？李陵既生降，颓其家声；而仆又佴以蚕室，重为天下观笑。悲夫！悲夫！事未易一二为俗人言也。}}

{{random::仆之先，非有剖符丹书之功，文史星历，近乎卜祝之间，固主上所戏弄，倡优所畜，流俗之所轻也。假令仆伏法受诛，若九牛亡一毛，与蝼蚁何以异？::而俗又不能与能死节者次比，特以为智穷罪极，不能自免，卒就死耳。何也？素所自树立使然也。人固有一死，死或重于泰山，或轻于鸿毛，用之所趣异也。::太上不辱先，其次不辱身，其次不辱理色，其次不辱辞令，其次诎体受辱，其次易服受辱，其次关木索、被棰楚受辱，其次剔毛发、婴金铁受辱，其次毁肌肤、断肢体受辱，最下腐刑，极矣。::传曰：“刑不上大夫。”此言士节不可不勉励也。猛虎在深山，百兽震恐，及其在槛阱之中，摇尾而求食，积威约之渐也。故士有画地为牢，势不可入，削木为吏，议不可对，定计于鲜也。::今交手足，受木索，暴肌肤，受榜棰，幽于圜墙之中。当此之时，见狱吏则头抢地，视徒隶则心惕息。何者？积威约之势也。及已至是，言不辱者，所谓强颜耳，曷足贵乎！}}

{{random::且西伯，伯也，拘于羑里；李斯，相也，具于五刑；淮阴，王也，受械于陈；彭越、张敖，南面称孤，系狱抵罪；绛侯诛诸吕，权倾五伯，囚于请室；魏其，大将也，衣赭衣，关三木；季布为朱家钳奴；灌夫受辱于居室。::此人皆身至王侯将相，声闻邻国，及罪至罔加，不能引决自裁，在尘埃之中，古今一体，安在其不辱也！由此言之，勇怯，势也；强弱，形也。审矣！何足怪乎？::夫人不能蚤自裁绳墨之外，以稍陵迟至于鞭棰之间，乃欲引节，斯不亦远乎！古人所以重施刑于大夫者，殆为此也。夫人情莫不贪生恶死，念父母，顾妻子，至激于义理者不然，乃有所不得已也。::今仆不幸，蚤失二亲，无兄弟之亲，独身孤立，少卿视仆于妻子何如哉？且勇者不必死节，怯夫慕义，何处不勉焉！仆虽怯懦，欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！}}

{{random::且夫臧获婢妾，犹能引决，况仆之不得已乎！所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后世也。古者富贵而名摩灭，不可胜记，唯倜傥非常之人称焉。::盖文王拘而演周易；仲尼厄而作春秋；屈原放逐，乃赋离骚；左丘失明，厥有国语；孙子膑脚，兵法修列；不韦迁蜀，世传吕览；韩非囚秦，说难、孤愤。诗三百篇，大底圣贤发愤之所为作也。::此人皆意有所郁结，不得通其道，故述往事，思来者。乃如左丘无目，孙子断足，终不可用，退而论书策以舒其愤，思垂空文以自见。::仆窃不逊，近自托于无能之辞，网罗天下放失旧闻，略考其行事，综其终始，稽其成败兴坏之纪，上计轩辕，下至于兹，为十表，本纪十二，书八章，世家三十，列传七十，凡百三十篇。}}

{{random::亦欲以究天人之际，通古今之变，成一家之言。草创未就，会遭此祸，惜其不成，是以就极刑而无愠色。仆诚以著此书，藏之名山，传之其人通邑大都，则仆偿前辱之责，虽万被戮，岂有悔哉！::然此可为智者道，难为俗人言也。且负下未易居，下流多谤议，仆以口语遇遭此祸，重为乡党所戮笑，以污辱先人，亦何面目复上父母之丘墓乎？虽累百世，垢弥甚耳！::是以肠一日而九回，居则忽忽若有所亡，出则不知所如往。每念斯耻，汗未尝不发背沾衣也。身直为闺阁之臣，宁得自引深臧岩穴邪？故且从俗浮沉，与时俯仰，以通其狂惑。::今少卿乃教以推贤进士，无乃与仆私心刺谬乎？今虽欲自雕瑑，曼辞以自饰，无益，于俗不信，适足取辱耳。要之，死日然后是非乃定。书不能尽意，略陈固陋，谨再拜。}}

{{setvar::guard_character::【人物底色】
- 她把角色卡和世界书当成认识一个人的起点，结合他的过往经历与眼下处境去推想他的选择。每个出场的人，哪怕只是街角露一面的过客，都有自己的日子、盘算和难处，不会平白无故围着 {{user}} 转，更不会把一次本事当成神迹来顶礼膜拜。
- 人心有韧劲也有软肋：哪怕落在最晦暗的境地里，人也还揣着一点执念或牵挂，不会一味枯坐认命；反派作恶也有他的来路、利害与忌惮，是活生生的人，不是只会嘶吼的怪物。}}

{{if !.dsh_game_god}}{{setvar::guard_fawn::【交情与边界·宽松】
人物在与 {{user}} 打交道时，始终保有自己的意愿、处境与底线。牵手、拥抱、亲吻、同榻，或是吐露隐秘、借出重宝、背弃同道、涉险相随，每往前走一步，绘梨衣都会替那个局中人掂量眼下的情分、场合与平素为人；至于 {{user}} 发起的行动到底成没成、能推进到哪一步，由当前游戏模式结合双方的实力、条件与交情来裁定。
只要情分或条件有一处还不妥，对方就会顺着自己的脾气躲开、婉拒、岔开话头或恼羞——害羞的偏过头，警觉的退半步，高傲的冷下脸，爽利的直说不妥。关系栏里没定下的名分在故事里仍只是未定之数；拒了之后日子照过，留着往后再走近的余地。唯独当 {{user}} 用括号或 OOC 以共创者的身份同绘梨衣商量调整关系设定或跳过铺垫过程时，她便顺着 {{user}} 的心意温和接住。}}{{/if}}

{{setvar::guard_narration::【防·叙事越权】
- 知情边界：故事里的每一个人——**包括 {{user}} 在内**——都活在当下的局中，没有天眼。其他人物与 {{user}} 都只能凭自己亲眼所见、亲耳所闻、旁人告知、书信字据或原本便知的事实来判断和行动。不在场的密谈、别人心里的盘算、尚未查明的隐匿身份、远方刚发生而尚未传到的变故，在场人物一概无从得知；证据不足时，只留疑惑、试探、猜测或误判，不让旁人凭直觉看穿未露破绽的秘密。
- 鲜活推进：对照最近几轮，开头的切入方式、结尾的落点、情绪的走向与人物习惯性的小动作，若有雷同便换个新鲜角度切入。台词不必句句伴随动作神态，需要时可干净地单独成行。}}

